/**
 * Trimmed excerpt of playwright@1.49.0 types/test.d.ts, kept structurally faithful:
 * JSDoc between members, multi-line signatures with nested option objects, overloads,
 * a plain property member, and a decoy interface sharing a name prefix.
 */

interface APIResponseAssertions {
  /**
   * Ensures the response status code is within `200..299` range.
   *
   * **Usage**
   *
   * ```js
   * await expect(response).toBeOK();
   * ```
   */
  toBeOK(): Promise<void>;

  /**
   * Makes the assertion check for the opposite condition.
   */
  not: APIResponseAssertions;
}

/**
 * The LocatorAssertions class provides assertion methods.
 */
interface LocatorAssertions {
  /**
   * Ensures the Locator points to an element with the given text.
   */
  toContainText(expected: string|RegExp|ReadonlyArray<string|RegExp>, options?: {
    ignoreCase?: boolean;

    timeout?: number;

    useInnerText?: boolean;
  }): Promise<void>;

  /**
   * Ensures the Locator points to an element with the given text.
   */
  toHaveText(expected: string|RegExp|ReadonlyArray<string|RegExp>, options?: {
    ignoreCase?: boolean;

    timeout?: number;
  }): Promise<void>;

  /**
   * Overload taking a name and a value.
   */
  toHaveAttribute(name: string, value: string|RegExp, options?: {
    timeout?: number;
  }): Promise<void>;

  /**
   * Overload taking only a name.
   */
  toHaveAttribute(name: string, options?: {
    timeout?: number;
  }): Promise<void>;

  /**
   * Deeply nested option object, to pin the inside-out collapse.
   */
  toHaveScreenshot(name: string|ReadonlyArray<string>, options?: {
    animations?: "disabled"|"allow";

    clip?: {
      x: number;

      y: number;
    };

    mask?: Array<Locator>;
  }): Promise<void>;

  not: LocatorAssertions;
}

interface PageAssertions {
  toHaveURL(urlOrRegExp: string|RegExp, options?: {
    timeout?: number;
  }): Promise<void>;

  not: PageAssertions;
}

/**
 * Decoy: shares a prefix with PageAssertions and is declared in the same file. A prefix match
 * would resolve PageAssertions to this and report options as if they were assertions.
 */
export interface PageAssertionsToHaveScreenshotOptions {
  animations?: "disabled"|"allow";

  timeout?: number;
}
